  ]
  console.log(readyBetween(plantings, "2027-06-10", "2027-06-25"))
}

function readyBetween(plantings, fromDate, toDate) {
  return plantings
    .filter(p => p.expectedHarvest >= fromDate && p.expectedHarvest <= toDate)
    .sort((a, b) => a.expectedHarvest.localeCompare(b.expectedHarvest))
    .map(p => p.crop)
    .join(", ")
}
